//This example will add up the subtotal of only visible lines instead of all lines like the total example does
//The 'If' at the end of txn.line.functions.sumFieldIf() is required for the conditional of 'txn.line.isVisible == true' to work.
//Removing the 'If' and the conditional and the ',' before it will make it an normal aggregate rule 
//You can comment out the current two lines (9 & 10) and uncomment out the other two lines (6 & 7) to switch between a conditionanal and standard aggregate.

//var subtotal = txn.line.functions.sumField(txn.line.pricing.extendedList);
//return subtotal;

var visableSubtotal = txn.line.functions.sumFieldIf(txn.line.pricing.extendedList, txn.line.isVisible == true, 0);
return visableSubtotal;
